export type EntityUpdate = {
    aliases?: Array<string> | null;
    name?: string | null;
    summary?: string | null;
};

export type EraseMe = {
    /**
     * You confirm that a workspace whose only member you are is closed with your account (everything
     * in it is deleted). Without it such a request is refused with `subject.workspace_closes`.
     */
    close_workspace?: boolean;
    /**
     * With two-step verification on: a code from your authenticator, unless you signed in with one in
     * the last 10 minutes (`auth.step_up_required` otherwise).
     */
    mfa_code?: string | null;
    /**
     * Your password, typed again. Required when the account has one.
     */
    password?: string | null;
};

export type ErasePerson = {
    /**
     * Confirms closing any workspace whose only member the person is.
     */
    close_workspace?: boolean;
    /**
     * With two-step verification on for your account: a code from your authenticator, unless you
     * signed in with one in the last 10 minutes (`auth.step_up_required` otherwise).
     */
    mfa_code?: string | null;
    /**
     * Your own password, typed again (an operator who signs in only with single sign-on confirms with a
     * sign-in from the last 10 minutes instead).
     */
    password?: string | null;
};

/**
 * The record a completed erasure leaves, for the People page (no personal data: an opaque reference,
 * per-category counts, the post-check result and the review counts).
 */
export type ErasureRecord = {
    completed_at?: string | null;
    /**
     * Rows removed or anonymised per category.
     */
    counts: {
        [key: string]: unknown;
    };
    /**
     * When it took its first irreversible step; none while it can still be cancelled.
     */
    deleting_at?: string | null;
    error?: string | null;
    id: string;
    /**
     * Rows still naming the person per table after the erasure: every value is 0 when it passed.
     */
    post_check: {
        [key: string]: unknown;
    };
    requested_at: string;
    /**
     * `self`, `operator` or `reapply` (a restore brought the person back and they were erased again).
     */
    requested_by: string;
    /**
     * Mentions of the person's email left in content other people wrote, for review.
     */
    review?: {
        [key: string]: unknown;
    };
    status: string;
    /**
     * The keyed hash of the erased account's id (never the id or the email).
     */
    subject_ref: string;
};

/**
 * An erasure as the routes report it.
 */
export type ErasureTicket = {
    id: string;
    requested_at: string;
    /**
     * `pending`, `running`, `held`, `done`, `failed` or `cancelled`.
     */
    status: string;
};

export type EventDetail = {
    attempts: number;
    body: {
        [key: string]: unknown;
    };
    claimed_until?: string | null;
    delivery_id: string;
    id: string;
    last_error?: string | null;
    received_at: string;
    /**
     * `pending`, `claimed`, `done` or `dead`.
     */
    status: string;
};

/**
 * A claimed event, for the consumer.
 */
export type EventOut = {
    /**
     * How many times this event has been handed out, this claim included.
     */
    attempts: number;
    /**
     * The delivery's JSON body, as sent.
     */
    body: {
        [key: string]: unknown;
    };
    /**
     * The sender's delivery id (`X-Delivery-Id`, `X-GitHub-Delivery` or `Idempotency-Key`), or one we made up.
     */
    delivery_id: string;
    /**
     * `extension_event:...`; pass it back to ack or nack.
     */
    id: string;
    received_at: string;
};

/**
 * What the exports list shows (never the archive).
 */
export type ExportRow = {
    created_at: string;
    error?: string | null;
    expires_at: string;
    id: string;
    /**
     * Categories and counts (empty until ready).
     */
    manifest?: {
        [key: string]: unknown;
    };
    requested_by?: string | null;
    /**
     * `self` (the person's own, every workspace) or `organisation` (an admin's, one workspace).
     */
    scope?: string;
    size_bytes?: number;
    /**
     * `pending`, `ready` or `failed`.
     */
    status: string;
    subject?: string | null;
};

export type ExtensionOut = {
    /**
     * Leased to a consumer right now.
     */
    claimed: number;
    created_at: string;
    /**
     * Handed out five times without an ack, or nacked at the last attempt (kept 30 days).
     */
    dead: number;
    description: string;
    /**
     * Acked, until they are pruned (7 days).
     */
    done: number;
    enabled: boolean;
    /**
     * `extension:...`
     */
    id: string;
    last_delivery_at?: string | null;
    name: string;
    /**
     * Waiting to be claimed, counting events whose lease ran out.
     */
    pending: number;
    /**
     * The last four characters of the current secret.
     */
    secret_hint: string;
    secret_rotated_at: string;
    updated_at: string;
    /**
     * The vault the script is expected to write to; `null` is your personal vault. Informational:
     * the script passes it as `vault_id` to the tools.
     */
    vault_id?: string | null;
    /**
     * Where senders POST: `{PUBLIC_URL}/hooks/ext/{key}`.
     */
    webhook_url: string;
};

/**
 * The only response that carries a secret in the clear.
 */
export type ExtensionWithSecret = {
    extension: ExtensionOut;
    /**
     * Shown once. Send it as `Authorization: Bearer <secret>`, or sign the body with it
     * (`X-Eunomia-Signature: sha256=<hex HMAC-SHA256>`). Rotate to get a new one.
     */
    secret: string;
};

/**
 * One field of one record type, from a sample.
 */
export type FieldProfile = {
    /**
     * For dates: the notation the values are written in, such as `YYYY-MM-DD` or `DD/MM/YYYY`.
     */
    date_format?: string | null;
    /**
     * Distinct values in the sample, counted up to 26 (26 means 26 or more).
     */
    distinct_count: number;
    /**
     * Every distinct value, for an enum candidate (25 or fewer).
     */
    enum_values?: Array<string> | null;
    inferred_type: InferredType;
    /**
     * Every sampled value differs (and there is at least one).
     */
    is_unique: boolean;
    max?: number | null;
    min?: number | null;
    /**
     * The share of sampled records with no value here (missing, null or blank), 0 to 1.
     */
    null_rate: number;
    /**
     * The payload key path (`billing.country`) or the CSV column.
     */
    path: string;
    record_type: string;
    sample_size: number;
    source: string;
    /**
     * The commonest values, most frequent first, at most five.
     */
    top_values: Array<TopValue>;
};

/**
 * What the pop-up sends. `value` is zeroised when this is dropped; Debug never prints it.
 */
export type FillBody = {
    /**
     * The hosts it may be sent to (defaults to what the agent asked for).
     */
    allowed_hosts?: Array<string> | null;
    /**
     * Let any credential of a vault member use it, not only the one that asked.
     */
    any_agent?: boolean;
    /**
     * `header`, `query`, `body` (defaults to what the agent asked for).
     */
    placements?: Array<string> | null;
    /**
     * The secret. Write-only: encrypted at once, never returned, logged or shown again.
     */
    value: string;
};

export type FillOut = {
    /**
     * `eu://<vault>/<name>`
     */
    handle: string;
    secret_id: string;
    status: string;
};

/**
 * Keeps entities whose value of `property` compares to `value` by `op` (`in` takes a list).
 */
export type Filter = {
    op: Op;
    property: string;
    /**
     * In the property's datatype; a list for `in`.
     */
    value: unknown;
};

