export type HelperAck = {
    /**
     * `false`: there is no updater on this server (no `update-status/`); switch the profile on by hand.
     */
    configured: boolean;
    requested: boolean;
};

export type HelperRequest = {
    enabled: boolean;
};

/**
 * The secrets helper's status for Settings.
 */
export type HelperStatus = {
    /**
     * The updater's request channel is there (`update-status/`): "Enable password managers" works.
     * When `false`, Settings shows the manual steps instead.
     */
    can_request: boolean;
    /**
     * The profile is on for this backend (`EUNOMIA_COMPOSE_PROFILES` names `secrets`).
     */
    enabled: boolean;
    /**
     * Why, for people (the updater's error, or why the helper is not answering).
     */
    message?: string | null;
    /**
     * `enable` or `disable` while a request waits for the updater.
     */
    pending?: string | null;
    /**
     * The compose profile to switch on by hand: `secrets`.
     */
    profile: string;
    /**
     * `helper_disabled` (off or starting) or `helper_unreachable` (unreachable): what a resolution
     * gets now; absent when running.
     */
    reason?: string | null;
    /**
     * `off` (the `secrets` profile is not on), `starting` (asked for, or started and not answering yet),
     * `running` (answers its health check) or `unreachable` (on, but not answering).
     */
    state: string;
    /**
     * The helper's version when running.
     */
    version?: string | null;
};

export type HoldChange = {
    /**
     * `true` places a legal hold (the account cannot be erased), `false` lifts it.
     */
    hold: boolean;
};

export type HoldState = {
    /**
     * An erasure of this account is open. A hold placed now parks it (`held`) before its next
     * irreversible step; lifting the hold resumes it.
     */
    erasure_open: boolean;
    /**
     * When the hold was placed, RFC 3339; none when there is no hold.
     */
    legal_hold_at?: string | null;
};

export type HookOut = {
    /**
     * The buffered event's id.
     */
    id: string;
    /**
     * `accepted`, or `duplicate` when this delivery id was already stored.
     */
    status: string;
};

/**
 * Body of the `POST /https` response.
 */
export type HttpsAck = {
    configured: boolean;
    /**
     * Present only when the updater is configured.
     */
    requested?: boolean | null;
};

/**
 * Body of `POST /https`: turn HTTPS on for a domain, or off.
 */
export type HttpsRequest = {
    /**
     * A public DNS name (eunomia.example.com). Required when enabling.
     */
    domain?: string;
    /**
     * Contact address for Let's Encrypt. Required when enabling.
     */
    email?: string;
    enabled: boolean;
};

/**
 * Documents `GET /https/status`. The handler merges the updater's
 * `https-status.json`, so everything except `configured` is absent when the
 * updater is not configured.
 */
export type HttpsStatus = {
    checked_at?: string | null;
    configured: boolean;
    domain?: string | null;
    message?: string | null;
    /**
     * `off`, `pending` (waiting for the certificate), `active` or `error`.
     */
    state?: string | null;
};

export type IdsBody = {
    /**
     * Event ids from a claim, at most 500.
     */
    ids: Array<string>;
};

/**
 * How to import a CSV's rows: the approved kind, the naming column, and optionally which column feeds which property.
 */
export type ImportBody = {
    as_of?: string | null;
    column_map?: {
        [key: string]: string;
    } | null;
    kind: string;
    name_column: string;
};

export type ImportOut = {
    /**
     * Link column values that name more than one entity, skipped.
     */
    ambiguous: Array<AmbiguousTarget>;
    /**
     * Rows and cells left out, at most 100 listed.
     */
    bad: Array<BadCell>;
    bad_count: number;
    columns: Array<ColumnUse>;
    /**
     * Entities made by this run, and ones it found and updated.
     */
    created: number;
    document_id: string;
    kind: string;
    /**
     * Relations this run wrote (a re-run writes none), and the link targets it created by name.
     */
    linked: number;
    /**
     * Link targets that already existed in another kind (an organisation a supplier column names),
     * linked to instead of a new entity.
     */
    reused: Array<ReusedTarget>;
    /**
     * Data rows in the file.
     */
    rows: number;
    /**
     * Names skipped because their kind was rejected and has no existing approved replacement.
     */
    skipped?: Array<SkippedTarget>;
    targets_created: number;
    updated: number;
    /**
     * Values written (each new or updated in place).
     */
    values: number;
};

/**
 * What an import of the CSV would do now.
 */
export type ImportPlan = {
    ambiguous: Array<AmbiguousTarget>;
    columns: Array<ColumnPlan>;
    /**
     * The kind its mapped properties belong to, once auto-mapping proposed them.
     */
    kind?: string | null;
    kind_status?: null | Status;
    /**
     * The column that names each row's entity: the first one no property or link is mapped from.
     */
    name_column?: string | null;
    /**
     * The kind is approved and at least one mapped property is: `document_import_rows` will run.
     */
    ready: boolean;
    reused: Array<ReusedTarget>;
    skipped?: Array<SkippedTarget>;
};

/**
 * What a field's values look like. The datatypes of a property, plus `id` for a key that names a
 * record (a link candidate).
 */
export type InferredType = 'text' | 'number' | 'integer' | 'money' | 'percent' | 'bool' | 'date' | 'datetime' | 'enum' | 'id';

export type IntegrityReport = {
    /**
     * True when the counter is behind the log (the next write's append would collide).
     */
    change_log_behind: boolean;
    change_log_counter: number;
    /**
     * Highest seq in the change log, and the counter the next write continues from.
     */
    change_log_top: number;
    /**
     * Memories whose subject entity no longer exists.
     */
    dangling_memories: Array<string>;
    /**
     * Relations with one end missing.
     */
    dangling_relations: Array<string>;
    /**
     * Memories filed here whose subject is in another vault (not repaired automatically).
     */
    misfiled_memories: Array<string>;
    /**
     * True when nothing below needs attention.
     */
    ok: boolean;
    repaired?: null | Repaired;
    vault: string;
};

