/**
 * An entity that already existed under a link column's value, in another kind than the link's
 * target: linked to as it is, never retyped and never duplicated.
 */
export type ReusedTarget = {
    column: string;
    entity_id: string;
    kind: string;
    name: string;
};

export type RoleRequest = {
    /**
     * `owner` or `member`
     */
    role: string;
};

export type Routing = {
    /**
     * Where records no rule matches go (`vault:...`); absent: your personal vault.
     */
    default_vault?: string | null;
    /**
     * Checked in order; the first match wins.
     */
    rules?: Array<Rule>;
};

/**
 * A value worked out for each entity before the metric combines them, such as stock × cost: two
 * terms and an operation, nested at most [`MAX_ROW_DEPTH`] deep. Typed data, never query text.
 */
export type RowExpr = {
    left: RowTerm;
    op: RowOp;
    right: RowTerm;
};

/**
 * How a row expression combines two values of one entity.
 */
export type RowOp = 'mul' | 'sub' | 'add' | 'div';

/**
 * One side of a row expression: a number, a property of the kind, or another row expression.
 */
export type RowTerm = number | string | RowExpr;

export type Rule = {
    /**
     * One of the connector's `routing_fields`.
     */
    field: string;
    /**
     * What the field must be (case-insensitive); for `title`, a word or phrase it contains.
     */
    value: string;
    /**
     * The vault a matching record goes to (`vault:...`).
     */
    vault: string;
};

export type SecurityChange = {
    /**
     * A current authenticator or recovery code, when your own account has two-step verification and its
     * last second factor is older than 10 minutes (`auth.step_up_required`).
     */
    mfa_code?: string | null;
    require_mfa: boolean;
};

export type SecurityOut = {
    /**
     * Every password account on this server, in every organisation, must pass two-step verification before
     * it gets a session. Accounts that sign in through single sign-on are left to the identity provider
     * unless they set up their own authenticator.
     */
    require_mfa: boolean;
    updated_at?: string | null;
    /**
     * Email of the operator who last changed it.
     */
    updated_by?: string | null;
    /**
     * Active password accounts on the whole server (every organisation) without two-step verification yet:
     * while it is required they are signed out and must set it up at their next sign-in.
     */
    without_mfa: number;
};

